INSERT INTO "WaqfPoint" ("ayahId", "wordIndex", "methodology", "status", "data")
VALUES (((SELECT id FROM "Ayah" WHERE "surahNumber" = 73 AND "numberInSurah" = 8), 0, 'BOOKS', 'APPROVED', '{"ruling":"تام","explanation":"لمن قرأ: «ربُّ» بالرفع خبر مبتدأ محذوف، أو رفعه بالابتداء والخبر جملة: «لا إله إلا هو» وبها قرأ أبو عمرو وعبد الله بن كثير ونافع وحفص عن عاصم (١)، وليس بوقف لمن جره على البدل من «ربك»، ومثله في عدم الوقف من جره بقسم مضمر كقولك الله لأفعلنَّ، وجوابه: لا إله إلَّا هو، ونسب هذا لابن عباس، قال أبو حيان: ولا يصح هذا عن ابن عباس؛ لأنَّ فيه إضمار الجار ولا يجيزه البصريون إلا مع لفظ الجلالة، ومن قرأه بالجر وهو حمزة والكسائي وابن عامر وأبو بكر عن عاصم فلا يقف على «تبتيلًا» (٢).","source":"Manar al-Huda (Ashmuni)","hukumIbtida":"جائز","taalil":""}');
