VALUES (((SELECT id FROM "Ayah" WHERE "surahNumber" = 80 AND "numberInSurah" = 17), 0, 'BOOKS', 'APPROVED', '{"ruling":"كافي","explanation":"«ما» اسم تعجب مبتدأ، أو اسم ناقص، أي: ما الذي أكفره، والوقف فصل بين الاستفهام والخبر، أي: من أي شيء خلقه، إن جعل استفهاما على معنى التقرير على حقارة ما خلق منه، كان الوقف على «خلقه» كافيًا، وإن جعل ما بعده بيانًا وتنبيهًا على حقارة ما خلق منه، فليس بوقف إلى قوله «أنشره».","source":"Manar al-Huda (Ashmuni)","hukumIbtida":"جائز","taalil":""}');
