INSERT INTO "WaqfPoint" ("ayahId", "wordIndex", "methodology", "status", "data")
VALUES (((SELECT id FROM "Ayah" WHERE "surahNumber" = 85 AND "numberInSurah" = 7), 0, 'BOOKS', 'APPROVED', '{"ruling":"تام","explanation":"على أنَّ جواب القسم «قتل أصحاب الأخدود»، وحذفت اللام من الجواب، أي: لقد قتل، بناء على أنَّه خبر لادعاء، وقيل هو: «أن الذين فتنوا» فالوقف على «الحريق» قال أبو جعفر: وأصح الأجوبة في جواب القسم «إنَّ بطش ربك لشديد»، واختلف في «الشاهد والمشهود»، فقيل: «الشاهد» أعضاء بني آدم، و «المشهود» ابن آدم دليله: «يوم تشهد عليهم ألسنتهم وأيديهم وأرجلهم بما كانوا يعملون» وقال الحسن: «الشاهد» يوم الجمعة و «المشهود» يوم القيامة. وقال ابن المسيب: «الشاهد» يوم التروية و «المشهود» يوم عرفة. وقيل: «الشاهد» يوم الاثنين و «المشهود» يوم الجمعة. وفيهما نحو من خمسة وعشرين قولًا ليس هذا محل ذكرها.","source":"Manar al-Huda (Ashmuni)","hukumIbtida":"جائز","taalil":""}');
