INSERT INTO "WaqfPoint" ("ayahId", "wordIndex", "methodology", "status", "data")
VALUES (((SELECT id FROM "Ayah" WHERE "surahNumber" = 88 AND "numberInSurah" = 7), 0, 'BOOKS', 'APPROVED', '{"ruling":"Tam","explanation":"وما بعده على حذف العاطف، أي: ووجوه؛ لأنَّ الذي تقدم «وجوه يومئذ خاشعة» وهذا الثاني معطوف عليه، وحذف لدلالة الكلام عليه ولا يوقف على: «ناعمة» لتعلق اللام، ومثله في عدم الوقف «راضية»؛ لأنه لا يبتدأ بحرف الجر.","source":"Manar al-Huda (Ashmuni)","hukumIbtida":"جائز","taalil":""}');
