INSERT INTO "WaqfPoint" ("ayahId", "wordIndex", "methodology", "status", "data")
VALUES (((SELECT id FROM "Ayah" WHERE "surahNumber" = 88 AND "numberInSurah" = 11), 0, 'BOOKS', 'APPROVED', '{"ruling":"Kafi","explanation":"على القراءتين، قرأ ابن كثير وأبو عمرو و «لا يُسمع» بالياء التحتية المضمومة مبنيًا للمفعول، «لاغيةٌ» بالرفع نائب الفاعل، وقرأ نافع كذلك إلا أنه بالتاء الفوقية والباقون بفتح التاء الفوقية ونصب «لاغيةً» (١)","source":"Manar al-Huda (Ashmuni)","hukumIbtida":"جائز","taalil":""}');
INSERT INTO "WaqfPoint" ("ayahId", "wordIndex", "methodology", "status", "data")
