INSERT INTO "WaqfPoint" ("ayahId", "wordIndex", "methodology", "status", "data")
VALUES (((SELECT id FROM "Ayah" WHERE "surahNumber" = 88 AND "numberInSurah" = 16), 0, 'BOOKS', 'APPROVED', '{"ruling":"Tam","explanation":"لتناهي صفة الأواني والفرش، والوقف على «خلقت» و «رفعت» و «نصبت» و «سطحت» كلها وقوف كافية للتفصيل بين أسباب الاعتبار، وقرأ العامة الأربعة مبنيات للمفعول والتاء ساكنة للتأنيث، وقرىء «خلقت» وما بعده بتاء المتكلم مبنيات للفاعل، ويجوز «فذكر» لمكان الفاء والوصل أولى.","source":"Manar al-Huda (Ashmuni)","hukumIbtida":"جائز","taalil":""}');
