INSERT INTO "WaqfPoint" ("ayahId", "wordIndex", "methodology", "status", "data")
VALUES (((SELECT id FROM "Ayah" WHERE "surahNumber" = 90 AND "numberInSurah" = 11), 0, 'BOOKS', 'APPROVED', '{"ruling":"كاف","explanation":"ومثله: «ما العقبة» ثم فسّر اقتحام العقبة، فقال: «فك رقبة أو إطعام «، ولا وقف من قوله: «فك رقبة» إلى «متربة» وهو جائز، ولا يرتقي إلى الحسن، وقد وسمه أبو حاتم وغيره بالتمام، وفيه نظر؛ لأنَّ: فك الرقبة، وإطعام اليتامى والمساكين لا تنفع إلاَّ مع الإيمان بالله. وفيه نظر؛ لأنَّه كله كلام واحد لأن فك الرقبة وإطعام اليتامى والمساكين لا تنفع إلاَّ مع الإيمان بالله، ولوجود حرف العطف بعده، وقيل: إن ثم، بمعنى: الواو وجيء بثم لبعد ما بين العتق والصدقة في الفضيلة، وبين الإيمان بالله؛ لأنهما لاينفعان إلاَّ بوجود الإيمان (٣).","source":"Manar al-Huda (Ashmuni)","hukumIbtida":"جائز","taalil":""}');
INSERT INTO "WaqfPoint" ("ayahId", "wordIndex", "methodology", "status", "data")
VALUES (((SELECT id FROM "Ayah" WHERE "surahNumber" = 90 AND "numberInSurah" = 14), 0, 'BOOKS', 'APPROVED', '{"ruling":"Qabih","explanation":"لأنَّ «يتيمًا» نصب بـ «إطعام» وفيه دليل على إعمال المصدر منونًا قال الشاعر: ضرب بالسيوف رؤوس قوم ... أزلنا هامهنَّ عن المقيل (٤)","source":"Manar al-Huda (Ashmuni)","hukumIbtida":"جائز","taalil":""}');
