INSERT INTO "WaqfPoint" ("ayahId", "wordIndex", "methodology", "status", "data")
VALUES (((SELECT id FROM "Ayah" WHERE "surahNumber" = 89 AND "numberInSurah" = 4), 0, 'BOOKS', 'APPROVED', '{"ruling":"كاف","explanation":"عند نافع على أنَّ جواب القسم محذوف تقديره: «لتبعثنَّ»، أو «لتعذبنَّ» يدل على ذلك قوله: «فصب عليهم ربك سوط عذاب»، وقال أبو حاتم: «لذي حجر»، وقال الأخفش جواب القسم: «إنَّ ربَّك لبالمرصاد» وهو التام.","source":"Manar al-Huda (Ashmuni)","hukumIbtida":"جائز","taalil":""}');
INSERT INTO "WaqfPoint" ("ayahId", "wordIndex", "methodology", "status", "data")
VALUES (((SELECT id FROM "Ayah" WHERE "surahNumber" = 89 AND "numberInSurah" = 6), 0, 'BOOKS', 'APPROVED', '{"ruling":"وقف عند نافع","explanation":"قال الكسائي: جيد، يقال: عاد الذين هم بإرم. وقال السدي: إرم قبيلة من عاد كانت تدعى إرم ذات العماد، يعني: أصحاب خيام لا يقيمون بعاد إرم، ليس بوقف؛ لأنَّ ما بعده نعت له، قرأ العامة (١): «.Background...» مصروفًا «إِرَمَ» بكسر الهمزة وفتح الراء والميم، اسم قبيلة، وقرأ الحسن (٢): «.Background...» غير مصروف مضافًا إلى «إرم» جعله اسم بلدة على حذف مضاف، أي: أهل إرم، وقال الصاغاني في (العباب في اللغة) من لم يضف جعل «إرم» ولم يصرفه؛ لأنه جعل «عاد» اسم أبيهم و «إرم» اسم القبيلة، وجعله بدلًا منه ومن أضاف ولم يصرف، جعله اسم أمهم أو اسم بلدة. اهـ.","source":"Manar al-Huda (Ashmuni)","hukumIbtida":"جائز","taalil":""}');
INSERT INTO "WaqfPoint" ("ayahId", "wordIndex", "methodology", "status", "data")
VALUES (((SELECT id FROM "Ayah" WHERE "surahNumber" = 89 AND "numberInSurah" = 7), 0, 'BOOKS', 'APPROVED', '{"ruling":"وقف عند نافع","explanation":"قال الكسائي: جيد، يقال: عاد الذين هم بإرم. وقال السدي: إرم قبيلة من عاد كانت تدعى إرم ذات العماد، يعني: أصحاب خيام لا يقيمون بعاد إرم، ليس بوقف؛ لأنَّ ما بعده نعت له، قرأ العامة (١): «.Background...» مصروفًا «إِرَمَ» بكسر الهمزة وفتح الراء والميم، اسم قبيلة، وقرأ الحسن (٢): «.Background...» غير مصروف مضافًا إلى «إرم» جعله اسم بلدة على حذف مضاف، أي: أهل إرم، وقال الصاغاني في (العباب في اللغة) من لم يضف جعل «إرم» ولم يصرفه؛ لأنه جعل «عاد» اسم أبيهم و «إرم» اسم القبيلة، وجعله بدلًا منه ومن أضاف ولم يصرف، جعله اسم أمهم أو اسم بلدة. اهـ.","source":"Manar al-Huda (Ashmuni)","hukumIbtida":"جائز","taalil":""}');
