INSERT INTO "WaqfPoint" ("ayahId", "wordIndex", "methodology", "status", "data")
VALUES (((SELECT id FROM "Ayah" WHERE "surahNumber" = 89 AND "numberInSurah" = 17), 0, 'BOOKS', 'APPROVED', '{"ruling":"جائز","explanation":"ومثله: «المسكين»، وكذا: «أكلًا لمَّا»، وقرئ «تكرمون» بالتاء الفوقية والياء التحتية، وكذا: المعاطيف عليه، قرأ أبو عمرو: «يكرمون»، والثلاثة بعده بالياء التحتية، والباقون بالتاء الفوقية في الجميع (٣)؛ خطابًا للإنسان المراد به الجنس وهو «تكرمون»، «ولا تحاضمون»،","source":"Manar al-Huda (Ashmuni)","hukumIbtida":"جائز","taalil":""}');
