INSERT INTO "WaqfPoint" ("ayahId", "wordIndex", "methodology", "status", "data")
VALUES (((SELECT id FROM "Ayah" WHERE "surahNumber" = 95 AND "numberInSurah" = 4), 0, 'BOOKS', 'APPROVED', '{"ruling":"Kafi","explanation":"إن أراد بالإنسان جميع الناس، وإن أراد به النبي - صلى الله عليه وسلم -، وثم رددناه، يعني: أبا جهل، كان الوقف على «تقويم» أكفى لا محالة.","source":"Manar al-Huda (Ashmuni)","hukumIbtida":"جائز","taalil":""}');
INSERT INTO "WaqfPoint" ("ayahId", "wordIndex", "methodology", "status", "data")
VALUES (((SELECT id FROM "Ayah" WHERE "surahNumber" = 95 AND "numberInSurah" = 5), 0, 'BOOKS', 'APPROVED', '{"ruling":"Hasan","explanation":"إن عنى بالإنسان الكافر، و «أسفل سافلين»: الدرك من النار، وليس بوقف، إن جعل «أسفل سافلين» في معنى: أرذل العمر والسافلون، الهرمى والزمني لأنَّ المؤمن إذا ردَّ إلى أرذل العمر كتب له مثل ما كان يعمل في صحته وقوته.","source":"Manar al-Huda (Ashmuni)","hukumIbtida":"جائز","taalil":""}');
INSERT INTO "WaqfPoint" ("ayahId", "wordIndex", "methodology", "status", "data")
