INSERT INTO "WaqfPoint" ("ayahId", "wordIndex", "methodology", "status", "data")
VALUES (((SELECT id FROM "Ayah" WHERE "surahNumber" = 97 AND "numberInSurah" = 3), 0, 'BOOKS', 'APPROVED', '{"ruling":"كافي","explanation":"ومثله من: «كل أمر»، والمعنى: تنزل الملائكة بكل أمر يكون في تلك السنة. وما قيل عن ابن عباس: من أنَّ الوقف «سلام» ويبتدئ: «هي»؛ على أنَّها خبر مبتدأ محذوف، والإشارة بذلك إلى أنَّها ليلة السابع والعشرين؛ لأنَّ لفظة: «هي» سابعة وعشرون من كلم هذه السورة، وكأنَّه قال: ليلة القدر الموافقة في العدد لفظة: «هي» من كلم هذه السورة لا ينبغي أن يعتقد صحته؛ لأنَّه الغاز وتغيير لنظم أفصح الكلام، وارتفع «سلام» خبرًا مقدمًا، و «هي» مبتدأ مؤخرًا، و «سلام» مبتدأ، و «هي» فاعل به عند الأخفش؛ لأنَّه لا يشترط الاعتماد في عمل الوصف وبعضهم يجعل الكلام تمَّ على «بإذن ربهم» ويعلق «من كل أمر» بما بعده، ومنهم من قال: الوقف عند من أجاز تعداد الأخبار «سلام هي» أي: من كل أمر هي سلام حتى مطلع الفجر، أي: تمتد إلى طلوع الفجر","source":"Manar al-Huda (Ashmuni)","hukumIbtida":"جائز","taalil":""}');
INSERT INTO "WaqfPoint" ("ayahId", "wordIndex", "methodology", "status", "data")
VALUES (((SELECT id FROM "Ayah" WHERE "surahNumber" = 98 AND "numberInSurah" = 1), 0, 'BOOKS', 'APPROVED', '{"ruling":"Kafi","explanation":"إن رفع «رسول» خبر مبتدأ محذوف، وليس بوقف إن رفع بدلًا من «البينة» إمَّا بدل اشتمال، أو بدل كل من كل، على سبيل المبالغة، جعل الرسول نفس البينة، أو على حذف مضاف، أي: بينة رسول.","source":"Manar al-Huda (Ashmuni)","hukumIbtida":"جائز","taalil":""}');
