INSERT INTO "WaqfPoint" ("ayahId", "wordIndex", "methodology", "status", "data")
VALUES (((SELECT id FROM "Ayah" WHERE "surahNumber" = 98 AND "numberInSurah" = 3), 0, 'BOOKS', 'APPROVED', '{"ruling":"Tam","explanation":"ومثله: «البينة»، ولا وقف من قوله: «وما أمروا» إلى «الزكاة» فلا يوقف على له «الدين» ولا على «حنفاء»؛ لأنَّ قوله: «ويقيموا الصلاة» موضعه نصب بالعطف على: «ليعبدوا» أو حذف النون علامة للنصب، فكأنَّه قال: إلَّا ليعبدوا وليقيموا.","source":"Manar al-Huda (Ashmuni)","hukumIbtida":"جائز","taalil":""}');
