VALUES (((SELECT id FROM "Ayah" WHERE "surahNumber" = 100 AND "numberInSurah" = 8), 0, 'BOOKS', 'APPROVED', '{"ruling":"Hasan","explanation":"قال الفراء: أصل نظم الآية أن يقال: وإنه لشديد الحب، فلما قدّم الحب، قال: لشديد، وحذف من آخره ذكر «الحب»؛ لأنَّه قد جرى ذكره، ولرؤوس الآي كقوله: «في يوم عاصف»، والعصوف للريح لا لليوم، كأنه قال: في يوم عاصف الريح","source":"Manar al-Huda (Ashmuni)","hukumIbtida":"جائز","taalil":""}');
